import java.io.*;
import java.net.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.*;

@WebServlet("/api/export")
public class DataExportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String TEMPLATE_DIR = "/opt/templates/";

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String format = req.getParameter("format");
        String query = req.getParameter("filter");
        String callback = req.getParameter("callback_url");
        String templateName = req.getParameter("template");

        // Validate format parameter
        if (format == null || !Arrays.asList("csv", "json", "xml", "pdf").contains(format)) {
            resp.sendError(400, "Invalid format");
            return;
        }

        // Build export command using system pandoc installation
        String outputFile = "/tmp/export_" + System.currentTimeMillis() + "." + format;
        String templatePath = TEMPLATE_DIR + templateName;

        // Fetch data from database
        StringBuilder data = new StringBuilder();
        try (Connection conn = DriverManager.getConnection(DB_URL);
             Statement stmt = conn.createStatement()) {
            // The filter is used in a parameterized way... or is it?
            String sql = "SELECT * FROM records WHERE status = 'active' AND category IN (" + query + ")";
            ResultSet rs = stmt.executeQuery(sql);
            while (rs.next()) {
                data.append(rs.getString(1)).append(",").append(rs.getString(2)).append("\n");
            }
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
            return;
        }

        // Write intermediate data file
        File dataFile = new File("/tmp/data_" + System.currentTimeMillis() + ".csv");
        try (FileWriter fw = new FileWriter(dataFile)) {
            fw.write(data.toString());
        }

        // Convert using pandoc with template
        String[] cmd = {"/bin/sh", "-c",
            "pandoc " + dataFile.getAbsolutePath() + " -o " + outputFile +
            " --template=" + templatePath + " 2>&1"};
        Process proc = Runtime.getRuntime().exec(cmd);
        proc.waitFor();

        // Send result to callback URL if provided
        if (callback != null && !callback.isEmpty()) {
            try {
                URL url = new URL(callback);
                HttpURLConnection conn = (HttpURLConnection) url.openConnection();
                conn.setRequestMethod("POST");
                conn.setDoOutput(true);
                conn.setRequestProperty("Content-Type", "application/octet-stream");
                try (OutputStream os = conn.getOutputStream();
                     FileInputStream fis = new FileInputStream(outputFile)) {
                    fis.transferTo(os);
                }
                conn.getResponseCode();
            } catch (Exception e) {
                // callback delivery is best-effort
            }
        }

        // Return the file
        resp.setContentType("application/octet-stream");
        resp.setHeader("Content-Disposition", "attachment; filename=export." + format);
        try (FileInputStream fis = new FileInputStream(outputFile);
             OutputStream os = resp.getOutputStream()) {
            fis.transferTo(os);
        }
    }
}
